// Task 90 — "Recommended setups" refresh engine.
//
// The BAKED-IN list (src/lib/algo-recommendations.ts, generated by
// scripts-tmp/gen-reco.ts) is the offline fallback; this module can re-run the
// exact same research sweep on demand (server-side, in-process background job):
// full-catalog sweeps (defaults + auto optimizer grid) across a symbol ×
// timeframe matrix at MAX history per timeframe, per-market costs, ranked by
// the panel's Calmar-style score. The winner is persisted to the AlgoRecoCache
// table and served by /api/algo/recommendations.
import { db } from '@/lib/db'
import { getBars } from '@/lib/alpaca'
import { TIMEFRAMES } from '@/lib/market-types'
import { prepareSeries, sweepStrategies, type BacktestConfig } from '@/lib/backtest'
import { ALGO_MAX_DAYS, ALGO_TIMEFRAMES, type AlgoTimeframe } from '@/lib/algo-strategies'
import { ALGO_RECOMMENDATIONS, ALGO_RECO_META, type AlgoRecommendation } from '@/lib/algo-recommendations'

export type { AlgoRecommendation }
export { ALGO_RECOMMENDATIONS as BAKED_RECOMMENDATIONS, ALGO_RECO_META as BAKED_RECO_META }

export const RECO_SYMBOLS = ['TSLA', 'AAPL', 'NVDA', 'SPY', 'BTC/USD', 'ETH/USD', 'SOL/USD']
export const RECO_MIN_TRADES = 10
export const RECO_TOPX = 10
export const RECO_POOL_TAKE = 3 // rows kept per combo for the global pool
export const RECO_CAP = 18 // final list size
const MAX_BARS = 120_000 // same hard cap the API route enforces
const CACHE_ID = 'algo-reco'

// Task 88 suggestions + realistic spreads (majors ~3 bps live, alts wider)
export const costsFor = (symbol: string): { slip: number; fee: number; spread: number } => {
  if (symbol.includes('/')) {
    const base = symbol.split('/')[0] ?? ''
    return base === 'BTC' || base === 'ETH' ? { slip: 3, fee: 10, spread: 3 } : { slip: 10, fee: 10, spread: 5 }
  }
  return { slip: 2, fee: 0, spread: 2 }
}

export const RECO_TOTAL_COMBOS = ALGO_TIMEFRAMES.length * RECO_SYMBOLS.length

// ---------------------------------------------------------------------------
// background job state (module-level — one refresh at a time per process)
// ---------------------------------------------------------------------------
interface RecoJobState {
  running: boolean
  done: number
  total: number
  startedAt: number
  finishedAt: number | null
  error: string | null
}
const g = globalThis as unknown as { __recoJob?: RecoJobState }
const job: RecoJobState = (g.__recoJob ??= { running: false, done: 0, total: RECO_TOTAL_COMBOS, startedAt: 0, finishedAt: null, error: null })

export function getRecoJobState(): RecoJobState {
  return job
}

/** Start a refresh (mutex-guarded). Returns false when one is already running. */
export function startRecoRefresh(userId: string): boolean {
  if (job.running) return false
  job.running = true
  job.done = 0
  job.total = RECO_TOTAL_COMBOS
  job.startedAt = Date.now()
  job.finishedAt = null
  job.error = null
  void (async () => {
    try {
      const feed = await runRecoSweepMatrix(userId, () => {
        job.done++
      })
      await db.algoRecoCache.upsert({
        where: { id: CACHE_ID },
        create: { id: CACHE_ID, generatedAt: new Date(feed.generatedAt), payload: JSON.stringify({ generatedAt: feed.generatedAt, method: feed.method, rows: feed.rows }) },
        update: { generatedAt: new Date(feed.generatedAt), payload: JSON.stringify({ generatedAt: feed.generatedAt, method: feed.method, rows: feed.rows }) },
      })
    } catch (e) {
      job.error = e instanceof Error ? (e.stack ?? e.message) : String(e)
      console.error('[algo-reco] refresh job failed:', e)
    } finally {
      job.running = false
      job.finishedAt = Date.now()
    }
  })()
  return true
}

export interface RecoFeed {
  generatedAt: string
  method: string
  rows: AlgoRecommendation[]
  source: 'db' | 'baked'
}

/** Newest persisted feed — DB cache when present, else the baked-in list. */
export async function getRecoFeed(): Promise<RecoFeed> {
  try {
    const row = await db.algoRecoCache.findUnique({ where: { id: CACHE_ID } })
    if (row) {
      const payload = JSON.parse(row.payload) as { generatedAt: string; method: string; rows: AlgoRecommendation[] }
      if (Array.isArray(payload.rows) && payload.rows.length > 0) {
        return { generatedAt: payload.generatedAt, method: payload.method, rows: payload.rows, source: 'db' }
      }
    }
  } catch {
    /* fall through to baked-in */
  }
  return { generatedAt: ALGO_RECO_META.generatedAt, method: ALGO_RECO_META.method, rows: ALGO_RECOMMENDATIONS, source: 'baked' }
}

// ---------------------------------------------------------------------------
// the matrix runner — same procedure as scripts-tmp/reco-sweep.ts
// ---------------------------------------------------------------------------
interface SweepComboRow {
  strategy: AlgoRecommendation['strategy']
  params: Record<string, number>
  score: number
  netPct: number
  pf: number
  winPct: number
  maxDDPct: number
  trades: number
}

export async function runRecoSweepMatrix(
  userId: string,
  onComboDone?: (done: number) => void,
): Promise<RecoFeed> {
  const t0 = Date.now()
  interface Combo {
    symbol: string
    tf: AlgoTimeframe
    bars: number
    from: number
    to: number
    coveredDays: number
    source: string
    costs: { slip: number; fee: number; spread: number }
    rows: SweepComboRow[]
  }
  const combos: Combo[] = []
  let completed = 0
  for (const tf of ALGO_TIMEFRAMES as readonly AlgoTimeframe[]) {
    for (const symbol of RECO_SYMBOLS) {
      const costs = costsFor(symbol)
      try {
        const days = ALGO_MAX_DAYS[tf]
        const res = await getBars(symbol, tf, userId, { lookbackDays: days })
        let bars = Array.isArray(res.bars) ? res.bars : []
        if (!res.demo && bars.length >= 80) {
          // drop the forming bar + hard cap (exact route semantics)
          const tfSec = TIMEFRAMES[tf].seconds
          const nowSec = Math.floor(Date.now() / 1000)
          while (bars.length > 0 && bars[bars.length - 1].time + tfSec > nowSec) bars = bars.slice(0, -1)
          if (bars.length > MAX_BARS) bars = bars.slice(bars.length - MAX_BARS)
          const cfg: BacktestConfig = {
            strategy: 'bb-reversion', // placeholder — sweep overrides per strategy
            params: {},
            qty: 10,
            sizingMode: 'fixed',
            riskBasis: 'usd',
            riskMoney: null,
            isCrypto: symbol.includes('/'),
            // the terminal's default bracket — recommendations apply this as-is
            tpMode: 'pct',
            tpValue: 1.5,
            slMode: 'pct',
            slValue: 1,
            maxTradesDay: 3,
            rthOnly: true,
            flattenEod: true,
            cooldownMin: 0,
            requireNewSignal: false,
            slippageBps: costs.slip,
            feeBps: costs.fee,
            spreadBps: costs.spread,
            capital: 10000,
          }
          const series = prepareSeries(bars)
          const sweep = sweepStrategies(series, cfg, { minTrades: RECO_MIN_TRADES, topX: RECO_TOPX })
          combos.push({
            symbol,
            tf,
            bars: series.n,
            from: bars[0].time,
            to: bars[bars.length - 1].time,
            coveredDays: Math.max(1, Math.round((nowSec - bars[0].time) / 86400)),
            source: res.source ?? 'alpaca',
            costs,
            rows: sweep.rows.slice(0, RECO_POOL_TAKE).map((r) => ({
              strategy: r.strategy,
              params: r.params,
              score: Number(r.score.toFixed(3)),
              netPct: Number(r.metrics.netPct.toFixed(2)),
              pf: Number(r.metrics.profitFactor.toFixed(2)),
              winPct: Number(r.metrics.winRate.toFixed(1)),
              maxDDPct: Number(r.metrics.maxDrawdownPct.toFixed(2)),
              trades: r.metrics.trades,
            })),
          })
        }
      } catch {
        /* unreachable feed for this combo — skip it, the rest still sweep */
      }
      completed++
      onComboDone?.(completed)
    }
  }
  // selection: per-combo rank-1 winners with a positive score, then globally
  // best remaining rows until the list is full (same rule as gen-reco.ts)
  const winners: { combo: Combo; row: SweepComboRow }[] = []
  const pool: { combo: Combo; row: SweepComboRow }[] = []
  for (const c of combos) {
    const [best, ...rest] = c.rows
    if (best && best.score > 0) winners.push({ combo: c, row: best })
    for (const r of rest) if (r.score > 0) pool.push({ combo: c, row: r })
  }
  pool.sort((a, b) => b.row.score - a.row.score)
  const picked = [...winners, ...pool].slice(0, RECO_CAP)
  picked.sort((a, b) => b.row.score - a.row.score)
  const rows: AlgoRecommendation[] = picked.map((p) => ({
    symbol: p.combo.symbol,
    timeframe: p.combo.tf,
    strategy: p.row.strategy,
    params: p.row.params,
    slipBps: p.combo.costs.slip,
    feeBps: p.combo.costs.fee,
    spreadBps: p.combo.costs.spread,
    score: p.row.score,
    netPct: p.row.netPct,
    pf: p.row.pf,
    winPct: p.row.winPct,
    maxDDPct: p.row.maxDDPct,
    trades: p.row.trades,
    bars: p.combo.bars,
    coveredDays: p.combo.coveredDays,
    from: p.combo.from,
    to: p.combo.to,
    source: p.combo.source,
  }))
  if (rows.length === 0) {
    throw new Error('No profitable configuration found across the whole matrix — nothing to recommend')
  }
  return {
    generatedAt: new Date(t0).toISOString(),
    method: ALGO_RECO_META.method,
    rows,
    source: 'db',
  }
}
